/*
 * Schriften von Mars-Strukto: „Mars Sans“ und „Mars Code“ – Teilmengen (Latein, Satzzeichen, Pfeile, Mathe) von Source Sans Pro und
 * Source Code Pro (© Adobe, SIL Open Font License 1.1, siehe fonts/OFL.txt), umbenannt, weil „Source“ ein reservierter Schriftname ist.
 * Im WOFF2-Format eingebettet (erzeugt mit build/schrift.py – nicht von Hand ändern).
 * Die Stile nennen zuerst 'Source Sans Pro' (lädt eine Seite wie Escape from Mars die Originale, nimmt der Browser diese), dann 'Mars Sans'.
 * Sonst meldet die Datei sie über die CSS Font Loading API an – ohne Schriftdateien vom Server, also auch auf fremden Seiten und per file://.
 */
'use strict';
window.SgSchrift = { daten: [
    ['Mars Sans', '400', 'normal', ''],
    ['Mars Sans', '600', 'normal', ''],
    ['Mars Sans', '700', 'normal', ''],
    ['Mars Sans', '400', 'italic', ''],
    ['Mars Code', '400', 'normal', ''],
    ['Mars Code', '700', 'normal', '']
] };
(function () {
  const S = window.SgSchrift;
  const bytes = (b64) => { const s = atob(b64); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u.buffer; };
  /* Base64 einer Schrift (für den Bild-Export) */
  S.base64 = (familie, gewicht, stil) => { const f = S.daten.find(x => x[0] === familie && x[1] === (gewicht || '400') && x[2] === (stil || 'normal')); return f ? f[3] : ''; };
  try {
    if (!document.fonts || typeof FontFace === 'undefined') return;
    const schonDa = (fam) => { for (const f of document.fonts) if (f.family.replace(/["']/g, '') === fam) return true; return false; };
    if (schonDa('Mars Sans')) return; // doppelt eingebunden
    for (const [fam, w, st, b64] of S.daten) {
      const ff = new FontFace(fam, bytes(b64), { weight: w, style: st });
      document.fonts.add(ff); ff.load().catch(() => { });
    }
  } catch (e) { /* ohne die Schriften nimmt der Browser Ersatzschriften – der Editor funktioniert trotzdem */ }
})();
